import React, {useState} from 'react';
import {Alert, Button, Checkbox, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, Radio, RadioGroup, Stack, Table, TableBody, TableCell, TableHead, TableRow, Typography} from '@mui/material';
import {EpassCard, EpassRecognition, EpassSchema} from './epassModels';
import {mergeSuggestions, newCard, normalizeSourceValue} from './epassDraft';

export default function EpassRecognitionDialog({result, schema, current, fileName, onClose, onApply}: {result: EpassRecognition; schema: EpassSchema; current: EpassCard; fileName: string; onClose: () => void; onApply: (cards: EpassCard[], replace: boolean) => void}) {
    const [mode, setMode] = useState(result.products.length === 1 ? 'current' : 'new');
    const [selected, setSelected] = useState(() => result.products.map(p => new Set(p.values.filter(v => result.products.length !== 1 || !current.values[v.field]?.trim()).map(v => v.field))));
    const changeMode = (value: string) => {setMode(value); setSelected(result.products.map(p => new Set(p.values.filter(v => value === 'new' || !current.values[v.field]?.trim()).map(v => v.field))));};
    const apply = () => {
        const cards = result.products.map((product, index) => {
            const values = Object.fromEntries(product.values.map(v => [v.field, normalizeSourceValue(v.value, schema.fields.find(f => f.key === v.field)!)]));
            return {...mergeSuggestions(mode === 'current' ? current : newCard(), values, selected[index]), sourceName: fileName, sourceText: result.rawText.slice(0, 12000)};
        }).filter((_, index) => selected[index].size > 0);
        onApply(cards, mode === 'current');
    };
    return <Dialog open onClose={onClose} maxWidth="md" fullWidth aria-labelledby="epass-recognition-title">
        <DialogTitle id="epass-recognition-title">Проверьте предложения ИИ</DialogTitle>
        <DialogContent dividers><Stack spacing={2}>
            <Alert severity="info">Отметьте сведения, которые хотите перенести. Уже заполненные поля изначально не выбраны. ИИ может ошибаться: особенно проверьте цифры, состав и перевод.</Alert>
            {result.warnings.map((warning, index) => <Alert severity="warning" key={index}>{warning}</Alert>)}
            {!result.products.length && <Alert severity="warning">Сведения о товарах не найдены. Можно заполнить карточку вручную.</Alert>}
            {result.products.length === 1 && <RadioGroup row value={mode} onChange={(_, value) => changeMode(value)}><FormControlLabel value="current" control={<Radio/>} label="В текущую карточку"/><FormControlLabel value="new" control={<Radio/>} label="Создать новую карточку"/></RadioGroup>}
            {result.products.map((product, index) => <Stack key={index} spacing={1}>
                <Typography variant="h6">Товар {index + 1}</Typography>
                <div style={{overflowX: 'auto'}}><Table size="small"><TableHead><TableRow><TableCell>Перенести</TableCell><TableCell>Поле</TableCell><TableCell>Предложение ИИ</TableCell>{mode === 'current' && <TableCell>Сейчас в карточке</TableCell>}</TableRow></TableHead><TableBody>
                    {product.values.map(v => <TableRow key={v.field}><TableCell><Checkbox checked={selected[index].has(v.field)} inputProps={{'aria-label': `Перенести ${schema.fields.find(f => f.key === v.field)?.label || v.field}`}} onChange={(_, checked) => setSelected(previous => previous.map((set, i) => {if (i !== index) return set; const next = new Set(set); checked ? next.add(v.field) : next.delete(v.field); return next;}))}/></TableCell><TableCell>{schema.fields.find(f => f.key === v.field)?.label || v.field}</TableCell><TableCell sx={{whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', maxWidth: 280}}>{v.value}</TableCell>{mode === 'current' && <TableCell sx={{maxWidth: 200, overflowWrap: 'anywhere'}}>{current.values[v.field] || '—'}</TableCell>}</TableRow>)}
                </TableBody></Table></div>
            </Stack>)}
            <details><summary style={{cursor: 'pointer'}}>Исходный текст распознавания</summary><Typography component="pre" sx={{whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', fontSize: 13}}>{result.rawText || 'Текст не распознан'}</Typography></details>
        </Stack></DialogContent>
        <DialogActions><Button onClick={onClose}>Закрыть</Button><Button variant="contained" disabled={!selected.some(s => s.size > 0)} onClick={apply}>Перенести выбранное</Button></DialogActions>
    </Dialog>;
}
