import React, {useEffect, useRef, useState} from 'react';
import {Accordion, AccordionDetails, AccordionSummary, Alert, Autocomplete, Box, Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, LinearProgress, Stack, TextField, Tooltip, Typography} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import ContentCopyOutlinedIcon from '@mui/icons-material/ContentCopyOutlined';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import DownloadOutlinedIcon from '@mui/icons-material/DownloadOutlined';
import UploadFileOutlinedIcon from '@mui/icons-material/UploadFileOutlined';
import AutoAwesomeOutlinedIcon from '@mui/icons-material/AutoAwesomeOutlined';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import styled from 'styled-components';
import {Link, useNavigate, useSearchParams} from 'react-router-dom';
import {suppliesApi, downloadSupplyDocument} from '../../supplies/suppliesApi';
import {SupplyView} from '../../supplies/supplyModels';
import ProductLifecycleLink from '../lifecycle/ProductLifecycleLink';
import {getActiveFirmId} from '../../../api/config';
import {useAuth} from '../../../auth/AuthContext';
import {MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, Surface} from '../../../ui/commonStyled/commonStyled';
import {epassApi, EpassApiError} from './epassApi';
import {combinedName, missingSuggestions, newCard, newDraft, readDraft} from './epassDraft';
import {EpassApplicant, EpassCard, EpassDraft, EpassField, EpassIssue, EpassRecognition, EpassSchema, EpassSource} from './epassModels';
import EpassImportDialog from './EpassImportDialog';
import EpassRecognitionDialog from './EpassRecognitionDialog';

const Layout = styled.div({display: 'grid', gridTemplateColumns: '260px minmax(0,1fr)', gap: 20, alignItems: 'start', '@media(max-width:850px)': {gridTemplateColumns: '1fr'}});
const Fields = styled.div({display: 'grid', gridTemplateColumns: 'repeat(2,minmax(0,1fr))', gap: 18, paddingTop: 10, '@media(max-width:600px)': {gridTemplateColumns: '1fr'}});
const Side = styled(Surface)({position: 'sticky', top: 16, padding: 16, display: 'grid', gap: 12, '@media(max-width:850px)': {position: 'static'}});
const ProductButton = styled.button<{$active: boolean}>(({ $active }) => ({textAlign: 'left', display: 'grid', gap: 5, padding: 12, width: '100%', minWidth: 0, cursor: 'pointer', color: 'var(--color-text)', background: $active ? 'var(--color-primary-soft)' : 'var(--color-surface)', border: `1px solid ${$active ? 'var(--color-primary)' : 'var(--color-border)'}`, borderRadius: 12, overflowWrap: 'anywhere', font: 'inherit', '&:focus-visible': {outline: '2px solid var(--color-primary)', outlineOffset: 2}}));

function FieldInput({field, value, error, onChange}: {field: EpassField; value: string; error?: string; onChange: (value: string) => void}) {
    const helper = error || (field.maxLength ? `${value.length} / ${field.maxLength}` : field.type === 'number' ? 'Число без единицы измерения' : '');
    const inputProps = {id: `epass-field-${field.key}`, label: field.label, size: 'small' as const, fullWidth: true, required: field.key === 'K', error: !!error, helperText: helper};
    return <Box sx={{gridColumn: field.multiline ? '1 / -1' : undefined, minWidth: 0}}>
        <Stack direction="row" spacing={0.5} alignItems="flex-start">
            {field.options.length > 0 ? <Autocomplete id={`epass-field-${field.key}`} fullWidth freeSolo={field.allowCustom} options={field.options}
                inputValue={field.allowCustom ? value : undefined}
                value={field.options.find(o => o.value === value) || (value ? {value, label: value} : null)}
                isOptionEqualToValue={(option, chosen) => option.value === chosen.value}
                getOptionLabel={option => typeof option === 'string' ? option : option.label}
                onChange={(_, option) => onChange(typeof option === 'string' ? option : option?.value || '')}
                onInputChange={(_, text, reason) => {if (reason === 'input' && field.allowCustom) onChange(text);}}
                renderInput={params => <TextField {...params} {...inputProps}/>}/>
                : <TextField {...inputProps} value={value} required={field.key === 'K'} type={field.type === 'date' ? 'date' : 'text'}
                    InputLabelProps={field.type === 'date' ? {shrink: true} : undefined} multiline={field.multiline} minRows={field.multiline ? 2 : undefined}
                    inputProps={{inputMode: field.type === 'number' ? 'decimal' : undefined}}
                    onChange={event => onChange(event.target.value)}/>}
            {!!field.hint && <Tooltip title={<span style={{whiteSpace: 'pre-line'}}>{field.hint}</span>} enterTouchDelay={0}><IconButton size="small" aria-label={`Подсказка: ${field.label}`}><HelpOutlineIcon fontSize="small"/></IconButton></Tooltip>}
        </Stack>
    </Box>;
}

function EpassWorkspace({storageKey, companyName, preparedBy, supply}: {storageKey: string; companyName: string; preparedBy: string; supply?: SupplyView}) {
    const [search, setSearch] = useSearchParams();
    const navigate = useNavigate();
    const batchId = supply ? '' : search.get('batch') || '';
    const [initial] = useState(() => {
        if (!supply) return readDraft(storageKey, newDraft(companyName, preparedBy));
        const saved = JSON.parse(supply.supply.state.epassApplicationJson) as Pick<EpassDraft, 'templateId' | 'applicant' | 'products'>;
        return {draft: {...saved, version: 1 as const, products: saved.products.map((p, index) => ({...newCard(p.values), sourceText: supply.supply.state.lines[index]?.rawText, sourceName: supply.supply.state.lines[index]?.name}))}, restored: true, error: ''};
    });
    const [supplyVersion, setSupplyVersion] = useState(supply?.supply.version || '');
    const [draft, setDraft] = useState<EpassDraft>(initial.draft);
    const latest = useRef(draft); latest.current = draft;
    const [activeId, setActiveId] = useState(draft.products[0].id);
    const active = draft.products.find(card => card.id === activeId) || draft.products[0];
    const [schema, setSchema] = useState<EpassSchema | null>(null);
    const [recognitionAvailable, setRecognitionAvailable] = useState(false);
    const [error, setError] = useState(initial.error);
    const [saveStatus, setSaveStatus] = useState(initial.restored ? 'Черновик восстановлен' : 'Новая заявка');
    const [busy, setBusy] = useState('');
    const [issues, setIssues] = useState<EpassIssue[]>([]);
    const [review, setReview] = useState(false);
    const [query, setQuery] = useState('');
    const [expanded, setExpanded] = useState(new Set(['identity']));
    const [applicantExpanded, setApplicantExpanded] = useState(true);
    const [deleteId, setDeleteId] = useState<string | null>(null);
    const [reset, setReset] = useState(false);
    const [source, setSource] = useState<EpassSource | null>(null);
    const [recognition, setRecognition] = useState<EpassRecognition | null>(null);
    const [file, setFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState('');
    const [headerRow, setHeaderRow] = useState(1);
    const [uploadOpen, setUploadOpen] = useState(false);
    const [exported, setExported] = useState(false);
    const uploadRef = useRef<HTMLInputElement>(null);
    const isPhoto = file && /\.(png|jpe?g|webp)$/i.test(file.name);

    useEffect(() => {
        const controller = new AbortController();
        epassApi.schema(controller.signal).then(result => {setSchema(result.schema); setRecognitionAvailable(result.recognitionAvailable);})
            .catch((e: Error) => {if (e.name !== 'AbortError') setError(e.message);});
        return () => controller.abort();
    }, []);
    useEffect(() => {
        if (!batchId) return;
        const controller = new AbortController();
        setBusy('Загружаем сохранённые черновики…');
        epassApi.fromRecognition(batchId, controller.signal).then(result => {
            if (!controller.signal.aborted) {setSource(result); setError('');}
        }).catch((failure: Error) => {
            if (!controller.signal.aborted) setError(failure.message);
        }).finally(() => {if (!controller.signal.aborted) setBusy('');});
        return () => controller.abort();
    }, [batchId]);
    useEffect(() => {
        if (supply) {setSaveStatus('Изменения формы сохраняются кнопкой «Сохранить заявку в поставку»'); return;}
        setSaveStatus('Сохраняем черновик…');
        const timer = window.setTimeout(() => {
            try {localStorage.setItem(storageKey, JSON.stringify(draft)); setSaveStatus('Черновик сохранен в этом браузере');}
            catch {setSaveStatus('Не удалось сохранить черновик. Скачайте файл до закрытия страницы.');}
        }, 350);
        return () => window.clearTimeout(timer);
    }, [draft, storageKey, supply]);
    useEffect(() => {
        if (supply) return;
        const persist = () => {try {localStorage.setItem(storageKey, JSON.stringify(latest.current));} catch { /* The page already reports storage failures. */ }};
        window.addEventListener('pagehide', persist);
        return () => {persist(); window.removeEventListener('pagehide', persist);};
    }, [storageKey, supply]);
    useEffect(() => {
        if (!file || !/\.(png|jpe?g|webp)$/i.test(file.name)) {setPreviewUrl(''); return;}
        const url = URL.createObjectURL(file); setPreviewUrl(url);
        return () => URL.revokeObjectURL(url);
    }, [file]);
    const updateApplicant = (key: keyof EpassApplicant, value: string) => {setDraft(previous => ({...previous, applicant: {...previous.applicant, [key]: value}})); setIssues([]);};
    const closeSource = () => {
        setSource(null);
        if (batchId) setSearch(previous => {const next = new URLSearchParams(previous); next.delete('batch'); return next;}, {replace: true});
    };
    const updateField = (key: string, value: string) => {setDraft(previous => ({...previous, products: previous.products.map(p => p.id === active.id ? {...p, values: {...p.values, [key]: value}} : p)})); setIssues([]);};
    const addCards = (cards: EpassCard[], replace = false) => {
        const removeBlank = draft.products.length === 1 && !Object.values(draft.products[0].values).some(v => v.trim());
        const products = replace ? draft.products.map(p => p.id === active.id ? {...cards[0], id: p.id} : p) : [...(removeBlank ? [] : draft.products), ...cards];
        if (products.length > (schema?.maxProducts || 1000)) {setError('В заявке допускается до 1000 товаров. Создайте отдельную заявку для остальных.'); return;}
        if (!cards.length) return;
        setDraft(previous => ({...previous, products})); setActiveId(replace ? active.id : cards[0].id); setIssues([]); closeSource(); setRecognition(null); setUploadOpen(false);
    };
    const run = async (label: string, action: () => Promise<void>) => {
        setBusy(label); setError('');
        try {await action();} catch (e) {setError(e instanceof Error ? e.message : 'Не удалось выполнить действие.'); if (e instanceof EpassApiError) setIssues(e.issues);}
        finally {setBusy('');}
    };
    const chooseFile = (selected: File | undefined) => {
        if (!selected) return;
        if (!/\.(xlsx|xls|csv|png|jpe?g|webp)$/i.test(selected.name) || selected.size > 10 * 1024 * 1024) {setError('Выберите Excel, CSV или фото (JPG, PNG, WebP) размером до 10 МБ.'); return;}
        setFile(selected); setHeaderRow(1); setError('');
    };
    const check = () => run('Проверяем заявку…', async () => {setIssues((await epassApi.validate(draft)).issues); setReview(true);});
    const download = () => run('Готовим Excel…', async () => {
        if (supply) {
            const result = await suppliesApi.action(supply.supply.id, 'epass/export', supplyVersion, {applicationJson: JSON.stringify(draft)});
            setSupplyVersion(result.supply.version);
            const document = result.documents.find(d => d.id === result.supply.state.epassApplicationFileId);
            try {if (document) await downloadSupplyDocument(result.supply.id, document.id, document.fileName);}
            finally {navigate(`/supplies/${supply.supply.id}`);}
            return;
        }
        const blob = await epassApi.export(draft); const url = URL.createObjectURL(blob);
        const link = document.createElement('a'); link.href = url; link.download = `Заявка_ePass_${draft.applicant.requestDate}.xlsx`;
        document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 30000); setReview(false); setExported(true);
    });
    const revealIssue = (issue: EpassIssue) => {
        setReview(false); setQuery('');
        if (issue.productIndex === null) setApplicantExpanded(true);
        if (issue.productIndex !== null && draft.products[issue.productIndex]) setActiveId(draft.products[issue.productIndex].id);
        const field = schema?.fields.find(f => f.key === issue.field);
        if (field) setExpanded(previous => new Set([...Array.from(previous), field.group]));
        window.setTimeout(() => {const input = document.getElementById(issue.productIndex === null ? `epass-applicant-${issue.field}` : `epass-field-${issue.field}`); input?.scrollIntoView({block: 'center', behavior: 'smooth'}); input?.focus();}, 350);
    };
    const cardIssues = issues.filter(issue => issue.productIndex === draft.products.findIndex(p => p.id === active.id));
    const applicantFields: [keyof EpassApplicant, string][] = [['companyName', 'Наименование заявителя'], ['gs1Number', 'Регистрационный номер ГС1 Беларуси'], ['requestDate', 'Дата подачи заявки'], ['preparedBy', 'Заявку подготовил(а)'], ['phone', 'Телефон'], ['email', 'Email']];

    return <MainDiv>
        <ProductLifecycleLink step={4}/>
        {supply && <Alert severity="info" sx={{mb: 2}}>Заявка поставки «{supply.supply.title}». Данные хранятся на сервере компании.
            <Button disabled={!!busy} onClick={() => run('Сохраняем заявку в поставку…', async () => {
                const result = await suppliesApi.action(supply.supply.id, 'epass', supplyVersion, {applicationJson: JSON.stringify(draft)}, 'PUT'); setSupplyVersion(result.supply.version); setSaveStatus('Заявка сохранена на сервере');
            })}>Сохранить заявку в поставку</Button><Button component={Link} to={`/supplies/${supply.supply.id}`}>Вернуться к поставке</Button>
        </Alert>}
        <PageHeader><PageTitleGroup><PageTitle>Формирование заявок в ePass</PageTitle><PageSubtitle>Подготовьте карточки новых товаров и скачайте заявку для национального каталога. Фото или файл поставщика помогут заполнить сведения.</PageSubtitle></PageTitleGroup>
            <Button variant="contained" size="large" startIcon={<DownloadOutlinedIcon/>} disabled={!!busy || !schema} onClick={check}>Проверить и скачать</Button></PageHeader>
        <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{mb: 2}}><Chip label="1 · Данные заявителя"/><Chip label="2 · Карточки товаров" color="primary" variant="outlined"/><Chip label="3 · Проверка и Excel"/><Chip label={`Шаблон: ${schema?.title || 'Корма для животных'}`} variant="outlined"/></Stack>
        {exported && <Alert severity="success" sx={{mb: 2}}>Excel подготовлен. Подайте заявку в ePASS самостоятельно. После регистрации загрузите результат с GTIN.
            <Button component={Link} to="/catalogGeneration/file">Загрузить результат регистрации</Button>
        </Alert>}
        {error && <Alert severity="error" onClose={() => setError('')} sx={{mb: 2}}>{error}{!schema && <Button onClick={() => window.location.reload()}>Повторить загрузку</Button>}</Alert>}
        {!!busy && <Box sx={{mb: 2}}><Typography variant="body2" role="status">{busy}</Typography><LinearProgress/></Box>}
        <Accordion expanded={applicantExpanded} onChange={(_, open) => setApplicantExpanded(open)} sx={{mb: 2, borderRadius: '12px !important'}}><AccordionSummary expandIcon={<ExpandMoreIcon/>}><Stack direction="row" spacing={1} alignItems="center"><Typography fontWeight={700}>Данные заявителя</Typography><Typography variant="body2" color="text.secondary">{draft.applicant.companyName || 'Укажите компанию'}</Typography></Stack></AccordionSummary>
            <AccordionDetails><Fields>{applicantFields.map(([key, label]) => <TextField key={key} id={`epass-applicant-${key}`} label={label} value={draft.applicant[key]} size="small" fullWidth required={['companyName', 'preparedBy', 'requestDate'].includes(key)} type={key === 'requestDate' ? 'date' : 'text'} InputLabelProps={key === 'requestDate' ? {shrink: true} : undefined} onChange={e => updateApplicant(key, e.target.value)} error={issues.some(i => i.productIndex === null && i.field === key)} helperText={issues.find(i => i.productIndex === null && i.field === key)?.message || (key === 'gs1Number' ? 'Номер участника ГС1, не GTIN товара' : '')}/>)}</Fields></AccordionDetails></Accordion>
        <Layout>
            <Side>
                <Typography variant="h6">Товары <Typography component="span" color="text.secondary">({draft.products.length})</Typography></Typography>
                {!supply && <Button variant="outlined" startIcon={<AddIcon/>} disabled={!!supply || draft.products.length >= 1000 || !!busy} onClick={() => {const card = newCard(); setDraft(p => ({...p, products: [...p.products, card]})); setActiveId(card.id); setIssues([]);}}>Добавить товар</Button>}
                <Stack spacing={1} sx={{maxHeight: {xs: 250, md: 470}, overflowY: 'auto', p: 0.5}}>{draft.products.map((card, index) => <ProductButton key={card.id} $active={active.id === card.id} onClick={() => setActiveId(card.id)} aria-pressed={active.id === card.id}><strong>{index + 1}. {card.values.K || 'Новый товар'}</strong><small>{card.values.L || 'Бренд не указан'}</small><small style={{color: 'var(--color-muted)'}}>{Object.values(card.values).filter(v => v.trim()).length} полей заполнено</small></ProductButton>)}</Stack>
                {!supply && <Button startIcon={<UploadFileOutlinedIcon/>} onClick={() => setUploadOpen(true)} disabled={!schema || !!busy}>Фото / файл поставщика</Button>}
                <Typography variant="caption" role="status" color={saveStatus.startsWith('Не удалось') ? 'error' : 'text.secondary'}>{saveStatus}</Typography>
                {!supply && <Button size="small" color="inherit" onClick={() => setReset(true)} disabled={!!busy}>Новая заявка</Button>}
            </Side>
            <Stack spacing={2} sx={{minWidth: 0}}>
                <Surface style={{padding: 20}}>
                    <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={1}><div><Typography variant="h6">{active.values.K || 'Карточка нового товара'}</Typography><Typography variant="body2" color="text.secondary">Заполните известные сведения. Остальные поля можно дополнить позднее.</Typography></div>
                        <Stack direction="row"><Tooltip title="Скопировать карточку"><span><IconButton disabled={!!supply || draft.products.length >= 1000 || !!busy} aria-label="Скопировать карточку" onClick={() => addCards([{...newCard({...active.values}), sourceName: active.sourceName, sourceText: active.sourceText}])}><ContentCopyOutlinedIcon/></IconButton></span></Tooltip><Tooltip title="Удалить товар"><span><IconButton aria-label="Удалить товар" disabled={!!supply || !!busy} onClick={() => setDeleteId(active.id)}><DeleteOutlineIcon/></IconButton></span></Tooltip></Stack></Stack>
                    <Box sx={{mt: 2, p: 1.5, borderRadius: 2, bgcolor: 'action.hover'}}><Typography variant="caption" color="text.secondary">Объединенное наименование для ePass · {combinedName(active.values).length} / 256</Typography><Typography sx={{overflowWrap: 'anywhere'}}>{combinedName(active.values) || 'Появится после ввода названия и бренда'}</Typography></Box>
                    {!!cardIssues.length && <Alert severity="error" sx={{mt: 2}}>{cardIssues.map((issue, i) => <Button key={i} size="small" color="inherit" onClick={() => revealIssue(issue)} sx={{display: 'block', textAlign: 'left'}}>{issue.message}</Button>)}</Alert>}
                    {active.sourceText && <details style={{marginTop: 16}}><summary style={{cursor: 'pointer'}}>Исходные сведения · {active.sourceName}</summary><Typography component="pre" sx={{whiteSpace: 'pre-wrap', fontSize: 13, overflowWrap: 'anywhere'}}>{active.sourceText}</Typography></details>}
                    <TextField size="small" fullWidth label="Найти поле в карточке" placeholder="Например: состав, срок годности, сертификат" value={query} onChange={e => setQuery(e.target.value)} sx={{mt: 2}}/>
                </Surface>
                {!schema && <Alert severity="info">Загружаем поля и справочники шаблона…</Alert>}
                {schema?.groups.map(group => {
                    const fields = schema.fields.filter(f => f.group === group.key && (!query || `${f.label} ${f.hint}`.toLowerCase().includes(query.toLowerCase())));
                    if (!fields.length) return null;
                    return <Accordion key={group.key} expanded={!!query || expanded.has(group.key)} onChange={(_, open) => setExpanded(previous => {const next = new Set(previous); open ? next.add(group.key) : next.delete(group.key); return next;})} sx={{borderRadius: '12px !important', m: '0 !important'}}>
                        <AccordionSummary expandIcon={<ExpandMoreIcon/>}><Stack direction="row" spacing={1} alignItems="center"><Typography fontWeight={700}>{group.label}</Typography><Chip size="small" variant="outlined" label={`${fields.filter(f => active.values[f.key]?.trim()).length} / ${fields.length}`}/></Stack></AccordionSummary>
                        <AccordionDetails><Fields>{fields.map(field => <FieldInput key={`${active.id}-${field.key}`} field={field} value={active.values[field.key] || ''} error={cardIssues.find(i => i.field === field.key)?.message} onChange={value => updateField(field.key, value)}/>)}</Fields></AccordionDetails>
                    </Accordion>;
                })}
                {schema && query && !schema.fields.some(f => `${f.label} ${f.hint}`.toLowerCase().includes(query.toLowerCase())) && <Alert severity="info">Поле не найдено. Попробуйте другое название.</Alert>}
                <Alert severity="info">GTIN для нового товара присваивается при регистрации. Система оставляет это служебное поле пустым. Неизвестные сведения не заполняйте словами «нет» или «неизвестно».</Alert>
                <Button variant="contained" size="large" startIcon={<DownloadOutlinedIcon/>} onClick={check} disabled={!!busy || !schema} sx={{alignSelf: 'flex-end'}}>Проверить и скачать</Button>
            </Stack>
        </Layout>
        <Dialog open={uploadOpen} onClose={() => {if (!busy) setUploadOpen(false);}} maxWidth="sm" fullWidth aria-labelledby="epass-upload-title"><DialogTitle id="epass-upload-title">Сведения от поставщика</DialogTitle><DialogContent dividers><Stack spacing={2}>
            <Alert severity="info">Можно ввести все вручную. Файл поможет перенести данные, а ИИ предложит заполнение по фото или тексту на любом языке.</Alert>
            <input ref={uploadRef} type="file" aria-label="Файл поставщика" hidden accept=".xlsx,.xls,.csv,.png,.jpg,.jpeg,.webp" onChange={e => {chooseFile(e.target.files?.[0]); e.target.value = '';}}/>
            <Button variant="outlined" startIcon={<UploadFileOutlinedIcon/>} onClick={() => uploadRef.current?.click()} disabled={!!busy}>Выбрать фото, Excel или CSV</Button>
            {file && <Typography sx={{overflowWrap: 'anywhere'}}>{file.name} · {(file.size / 1024).toFixed(0)} КБ</Typography>}
            {previewUrl && <Box component="img" src={previewUrl} alt="Фото товара от поставщика" sx={{maxWidth: '100%', maxHeight: 300, objectFit: 'contain'}}/>}
            {file && !isPhoto && <><TextField type="number" size="small" label="Строка с заголовками колонок" value={headerRow} inputProps={{min: 1, max: 20}} onChange={e => setHeaderRow(Number(e.target.value))} helperText="Читаем первый лист. Для файла ePass строка определяется автоматически."/><Button variant="contained" disabled={!!busy || headerRow < 1 || headerRow > 20} onClick={() => run('Читаем файл…', async () => {setSource(await epassApi.import(file, headerRow)); setUploadOpen(false);})}>Сопоставить колонки и перенести</Button></>}
            <Button variant="outlined" startIcon={<AutoAwesomeOutlinedIcon/>} disabled={!file || !recognitionAvailable || !!busy || headerRow < 1 || headerRow > 20} onClick={() => file && run('Распознаем сведения…', async () => {setRecognition(await epassApi.recognize(file, headerRow)); setUploadOpen(false);})}>Распознать с ИИ</Button>
            <Typography variant="caption" color="text.secondary">{recognitionAvailable ? 'При нажатии «Распознать с ИИ» фото или данные файла передаются подключенному ИИ-сервису. Перед переносом вы проверите предложения.' : 'ИИ не подключен на сервере. Ручной ввод и сопоставление колонок Excel/CSV доступны.'}</Typography>
            {!!busy && <><Typography role="status">{busy}</Typography><LinearProgress/></>}{error && <Alert severity="error">{error}</Alert>}
        </Stack></DialogContent><DialogActions><Button disabled={!!busy} onClick={() => setUploadOpen(false)}>Закрыть</Button></DialogActions></Dialog>
        {source && schema && <EpassImportDialog source={source} schema={schema} onClose={closeSource} onApply={cards => addCards(cards)}/>}
        {recognition && schema && <EpassRecognitionDialog result={recognition} schema={schema} current={active} fileName={file?.name || ''} onClose={() => setRecognition(null)} onApply={addCards}/>}
        <Dialog open={review} onClose={() => {if (!busy) setReview(false);}} fullWidth maxWidth="md" aria-labelledby="epass-review-title"><DialogTitle id="epass-review-title">Проверка заявки перед скачиванием</DialogTitle><DialogContent dividers><Stack spacing={2}>
            <Typography>{draft.applicant.companyName || 'Заявитель не указан'} · товаров: {draft.products.length}</Typography>
            {!!issues.length ? <Alert severity="error">Исправьте ошибки, чтобы скачать файл.{issues.map((issue, i) => <Button key={i} color="inherit" size="small" sx={{display: 'block', textAlign: 'left'}} onClick={() => revealIssue(issue)}>{issue.productIndex !== null ? `Товар ${issue.productIndex + 1}: ` : ''}{issue.message}</Button>)}</Alert> : <Alert severity="success">Формат заполненных полей проверен. Проверьте полноту и достоверность сведений перед отправкой в ePass.</Alert>}
            {!draft.applicant.gs1Number && <Alert severity="warning">Регистрационный номер участника ГС1 не указан.</Alert>}
            {draft.products.map((card, index) => <Box key={card.id} sx={{p: 2, bgcolor: 'action.hover', borderRadius: 2}}><Typography fontWeight={700}>{index + 1}. {combinedName(card.values) || 'Название не заполнено'}</Typography><Typography variant="body2">{card.values.AV || 'Производитель не указан'}{card.values.W && ` · ${card.values.W} ${card.values.V || ''}`}</Typography>{!!missingSuggestions(card).length && <Typography variant="body2" color="text.secondary" sx={{mt: 1}}>Стоит дополнить: {missingSuggestions(card).join(', ')}.</Typography>}<Button size="small" onClick={() => {setActiveId(card.id); setReview(false);}}>Открыть карточку</Button></Box>)}
            <Typography variant="caption" color="text.secondary">Скачивание готовит файл по шаблону «Корма для животных». Загрузите его в ePass самостоятельно; прием файла проверяет каталог.</Typography>
            {error && <Alert severity="error">{error}</Alert>}{!!busy && <LinearProgress/>}
        </Stack></DialogContent><DialogActions><Button disabled={!!busy} onClick={() => setReview(false)}>Вернуться к форме</Button><Button variant="contained" startIcon={<DownloadOutlinedIcon/>} disabled={!!issues.length || !!busy} onClick={download}>Скачать Excel для ePass</Button></DialogActions></Dialog>
        <Dialog open={!!deleteId || reset} onClose={() => {setDeleteId(null); setReset(false);}}><DialogTitle>{reset ? 'Начать новую заявку?' : 'Удалить товар из заявки?'}</DialogTitle><DialogContent>{reset ? 'Текущий черновик будет заменен. При необходимости сначала скачайте Excel.' : 'Карточка будет удалена из текущего черновика.'}</DialogContent><DialogActions><Button onClick={() => {setDeleteId(null); setReset(false);}}>Отмена</Button><Button color="error" onClick={() => {
            if (reset) {const fresh = newDraft(companyName, preparedBy); setDraft(fresh); setActiveId(fresh.products[0].id); setFile(null); setIssues([]);}
            else {const remaining = draft.products.filter(p => p.id !== deleteId); const products = remaining.length ? remaining : [newCard()]; setDraft(p => ({...p, products})); setActiveId(products[0].id); setIssues([]);}
            setDeleteId(null); setReset(false);
        }}>{reset ? 'Начать новую' : 'Удалить'}</Button></DialogActions></Dialog>
    </MainDiv>;
}

export default function EpassPage() {
    const {user} = useAuth();
    const [search] = useSearchParams();
    const supplyId = search.get('supply');
    if (supplyId) return <SupplyApplication key={`${getActiveFirmId()}.${user?.id}.${supplyId}`} id={supplyId}/>;
    const storageKey = `vivotech.epass.v1.${getActiveFirmId()}.${user?.id || 'user'}`;
    return <EpassWorkspace key={storageKey} storageKey={storageKey} companyName={user?.firmName || ''} preparedBy={user?.name || ''}/>;
}

function SupplyApplication({id}: {id: string}) {
    const [supply, setSupply] = useState<SupplyView | null>(null); const [error, setError] = useState('');
    useEffect(() => {const controller = new AbortController(); suppliesApi.get(id, controller.signal).then(setSupply).catch((failure: Error) => {if (!controller.signal.aborted) setError(failure.message);}); return () => controller.abort();}, [id]);
    if (error) return <MainDiv><Alert severity="error">{error}</Alert><Button component={Link} to={`/supplies/${id}`}>Вернуться к поставке</Button></MainDiv>;
    if (!supply) return <MainDiv><LinearProgress/></MainDiv>;
    if (supply.supply.state.step !== 4) return <MainDiv><Alert severity="info">Заявка доступна для редактирования на этапе 4. Откройте карточку поставки, чтобы продолжить текущий этап или вернуться для исправления.</Alert><Button component={Link} to={`/supplies/${id}`}>Вернуться к поставке</Button></MainDiv>;
    return <EpassWorkspace storageKey={`vivotech.supply.epass.${id}`} companyName="" preparedBy="" supply={supply}/>;
}
