import {firmApiUrl, getAccessToken} from '../../../api/config';
import {EpassDraft, EpassIssue, EpassRecognition, EpassSchema, EpassSource} from './epassModels';

export class EpassApiError extends Error {
    constructor(message: string, public issues: EpassIssue[] = []) {super(message);}
}
const request = async (path: string, init: RequestInit = {}): Promise<Response> => {
    const headers = new Headers(init.headers);
    const token = getAccessToken();
    if (token) headers.set('Authorization', `Bearer ${token}`);
    let response: Response;
    try {response = await fetch(firmApiUrl(`epass/${path}`), {...init, headers});}
    catch (error) {if (error instanceof Error && error.name === 'AbortError') throw error; throw new EpassApiError('Не удалось связаться с сервером. Черновик сохранен в этом браузере.');}
    if (!response.ok) {
        const body = await response.json().catch(() => ({}));
        throw new EpassApiError(typeof body.message === 'string' ? body.message : typeof body.detail === 'string' ? body.detail : response.status === 401 ? 'Войдите в CRM заново.' : 'Сервер не смог обработать запрос.', Array.isArray(body.issues) ? body.issues : []);
    }
    return response;
};
const jsonBody = (draft: EpassDraft) => ({method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({templateId: draft.templateId, applicant: draft.applicant, products: draft.products.map(p => ({values: p.values}))})});
const upload = async <T,>(path: string, file: File, headerRow: number): Promise<T> => {
    const data = new FormData(); data.append('file', file); data.append('headerRow', String(headerRow));
    return (await request(path, {method: 'POST', body: data})).json();
};
export const epassApi = {
    fromRecognition: async (batchId: string, signal?: AbortSignal): Promise<EpassSource> => (await request(`recognition/${encodeURIComponent(batchId)}`, {signal})).json(),
    schema: async (signal?: AbortSignal): Promise<{schema: EpassSchema; recognitionAvailable: boolean}> => (await request('schema', {signal})).json(),
    validate: async (draft: EpassDraft): Promise<{issues: EpassIssue[]}> => (await request('validate', jsonBody(draft))).json(),
    export: async (draft: EpassDraft): Promise<Blob> => (await request('export', jsonBody(draft))).blob(),
    import: (file: File, headerRow: number): Promise<EpassSource> => upload('import', file, headerRow),
    recognize: (file: File, headerRow: number): Promise<EpassRecognition> => upload('recognize', file, headerRow),
};
