import React, {useMemo, useState} from 'react';
import {Alert, Autocomplete, Button, Checkbox, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, Stack, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, TextField, Typography} from '@mui/material';
import {EpassCard, EpassSchema, EpassSource} from './epassModels';
import {cardsFromSource} from './epassDraft';

export default function EpassImportDialog({source, schema, onClose, onApply}: {source: EpassSource; schema: EpassSchema; onClose: () => void; onApply: (cards: EpassCard[]) => void}) {
    const [mapping, setMapping] = useState<Record<string, string>>(() => Object.fromEntries(source.columns.map(c => [c.key, c.suggestedField || ''])));
    const [selected, setSelected] = useState(() => new Set(source.rows.map(row => row.rowNumber)));
    const [page, setPage] = useState(0);
    const duplicates = Object.values(mapping).filter((value, index, values) => value && values.indexOf(value) !== index);
    const cards = useMemo(() => cardsFromSource(source, mapping, schema, selected), [source, mapping, schema, selected]);
    const fieldOptions = useMemo(() => [...schema.fields].sort((a, b) => schema.groups.findIndex(g => g.key === a.group) - schema.groups.findIndex(g => g.key === b.group) || a.number - b.number), [schema]);
    const hasMapping = Object.values(mapping).some(Boolean);
    const visible = source.rows.slice(page * 25, page * 25 + 25);
    return <Dialog open onClose={onClose} maxWidth="lg" fullWidth aria-labelledby="epass-import-title">
        <DialogTitle id="epass-import-title">Данные из Excel / CSV</DialogTitle>
        <DialogContent dividers>
            <Stack spacing={2}>
                <Typography>{source.fileName} · лист «{source.sheetName}» · товаров: {source.rows.length}</Typography>
                {source.warnings?.map((warning, index) => <Alert key={index} severity="warning">{warning}</Alert>)}
                <Alert severity="info">Укажите, в какие поля перенести колонки поставщика. Несопоставленные колонки сохранятся в исходных сведениях карточки. Проверьте язык, единицы и значения после переноса.</Alert>
                <Typography variant="h6">1. Сопоставьте колонки</Typography>
                <Stack spacing={1.5} sx={{maxHeight: 350, overflowY: 'auto', p: 1}}>
                    {source.columns.filter(c => source.rows.some(row => row.values[c.key])).map(column => <Stack key={column.key} direction={{xs: 'column', sm: 'row'}} spacing={1.5} alignItems={{sm: 'center'}}>
                        <Stack sx={{flex: 1, minWidth: 0}}><Typography fontWeight={600} sx={{overflowWrap: 'anywhere'}}>{column.header}</Typography><Typography variant="caption" color="text.secondary" sx={{overflowWrap: 'anywhere'}}>{source.rows.find(row => row.values[column.key])?.values[column.key]?.slice(0, 180)}</Typography></Stack>
                        <Autocomplete options={fieldOptions} groupBy={field => schema.groups.find(g => g.key === field.group)?.label || ''}
                            getOptionLabel={field => field.label} value={schema.fields.find(f => f.key === mapping[column.key]) || null}
                            onChange={(_, field) => setMapping(previous => ({...previous, [column.key]: field?.key || ''}))}
                            sx={{width: {xs: '100%', sm: 330}}} renderInput={params => <TextField {...params} size="small" label={`Поле для «${column.header}»`} placeholder="Пропустить колонку"/>}/>
                    </Stack>)}
                </Stack>
                {!!duplicates.length && <Alert severity="error">Несколько колонок назначены одному полю. Выберите разные поля или уберите лишнее сопоставление.</Alert>}
                <Typography variant="h6">2. Выберите товары</Typography>
                <FormControlLabel control={<Checkbox checked={selected.size === source.rows.length} indeterminate={selected.size > 0 && selected.size < source.rows.length}
                    onChange={(_, checked) => setSelected(checked ? new Set(source.rows.map(r => r.rowNumber)) : new Set())}/>} label={`Все товары (${selected.size} выбрано)`}/>
                <TableContainer sx={{maxHeight: 350}}><Table size="small" stickyHeader><TableHead><TableRow><TableCell>Выбрать</TableCell><TableCell>Строка</TableCell><TableCell>Наименование после переноса</TableCell><TableCell>Производитель</TableCell></TableRow></TableHead>
                    <TableBody>{visible.map(row => {
                        const card = cardsFromSource(source, mapping, schema, new Set([row.rowNumber]))[0];
                        return <TableRow key={row.rowNumber}><TableCell><Checkbox inputProps={{'aria-label': `Выбрать строку ${row.rowNumber}`}} checked={selected.has(row.rowNumber)} onChange={(_, checked) => setSelected(previous => {const next = new Set(previous); checked ? next.add(row.rowNumber) : next.delete(row.rowNumber); return next;})}/></TableCell><TableCell>{row.rowNumber}</TableCell><TableCell>{card.values.K || 'Наименование нужно заполнить'}</TableCell><TableCell>{card.values.AV || '—'}</TableCell></TableRow>;
                    })}</TableBody></Table></TableContainer>
                {source.rows.length > 25 && <Stack direction="row" spacing={1} alignItems="center"><Button disabled={page === 0} onClick={() => setPage(p => p - 1)}>Назад</Button><Typography>{page + 1} / {Math.ceil(source.rows.length / 25)}</Typography><Button disabled={(page + 1) * 25 >= source.rows.length} onClick={() => setPage(p => p + 1)}>Далее</Button></Stack>}
            </Stack>
        </DialogContent>
        <DialogActions><Button onClick={onClose}>Отмена</Button><Button variant="contained" disabled={!hasMapping || !selected.size || !!duplicates.length} onClick={() => onApply(cards)}>Добавить карточки ({selected.size})</Button></DialogActions>
    </Dialog>;
}
